const STORAGE_KEY = 'vibetodo-workspace-v1';
const uid = () => Math.random().toString(36).slice(2, 9);
const demoData = { selectedProjectId:'p1', projects:[{id:'p1',name:'vibetodo',description:'여러 프로젝트의 바이브 코딩 흐름을 한 곳에서 관리합니다.',color:'#b9f56b',notes:['한 번에 하나의 TODO만 진행하기','기능 구현 후 바로 검증하기'],files:[{id:'f1',name:'MVP 출시',fileName:null,todos:[{id:'t1',title:'프로젝트 대시보드 레이아웃 구성',status:'done',priority:'high',estimate:'1h'},{id:'t2',title:'프로젝트별 TODO 파일 모델 만들기',status:'done',priority:'high',estimate:'1.5h'},{id:'t3',title:'진행률과 다음 TODO 카드 연결',status:'doing',priority:'high',estimate:'1h'},{id:'t4',title:'JSON 백업 / 복원 기능 추가',status:'todo',priority:'medium',estimate:'1h'}]},{id:'f2',name:'다음 개선',fileName:null,todos:[{id:'t5',title:'키보드 단축키 지원',status:'todo',priority:'low',estimate:'30m'},{id:'t6',title:'마감일과 알림 추가',status:'todo',priority:'medium',estimate:'2h'}]}]}]};
let data = load(); let activeFileId = null; let filter = 'all'; let viewMode = 'dashboard';
function separateProjectPaths(result){const migrating=result.pathModelVersion!==2;(result.projects||[]).forEach(p=>{if(!p.projectPath||(migrating&&p.projectPath===p.folderPath))p.projectPath='';});result.pathModelVersion=2;return result;}
function load(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));const result=saved||structuredClone(demoData);if(!Array.isArray(result.dashboardItems))result.dashboardItems=[];if(!Array.isArray(result.weeklyReports))result.weeklyReports=[];return separateProjectPaths(result);}catch{const result=structuredClone(demoData);result.dashboardItems=[];result.weeklyReports=[];return separateProjectPaths(result);}}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(data));document.querySelector('#save-status').textContent='자동 저장됨 · 방금';}
function project(){return data.projects.find(p=>p.id===data.selectedProjectId)||data.projects[0];}
function allTodos(p){return p.files.flatMap(f=>f.todos||[]);}
function activeFile(p){return p.files.find(f=>f.id===activeFileId)||p.files[0];}
function escapeHtml(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function parseMarkdown(content){
  const lines=content.split(/\r?\n/); const todos=[];
  lines.forEach((line,lineIndex)=>{const match=line.match(/^(\s*[-*+]\s+)\[([ xX>])\]\s+(.*)$/);if(!match)return;let title=match[3].trim();let priority='medium';if(/^\[(high|medium|low)\]\s*/i.test(title)){priority=title.match(/^\[(high|medium|low)\]/i)[1].toLowerCase();title=title.replace(/^\[(high|medium|low)\]\s*/i,'');}const dueMatch=title.match(/\s+\[due:([^\]]+)\]\s*$/i);const due=dueMatch?.[1]?.trim()||'';if(due)title=title.replace(/\s+\[due:[^\]]+\]\s*$/i,'');const estimate=title.match(/\s+\(([^)]+)\)$/)?.[1]||'';if(estimate)title=title.replace(/\s+\([^)]+\)$/,'');todos.push({id:uid(),title,status:match[2].toLowerCase()==='x'?'done':match[2]==='>'?'hold':'todo',priority,estimate,due,lineIndex,prefix:match[1],originalLine:line});});
  return todos;
}
function markdownLine(todo){return `${todo.prefix||'- '}[${todo.status==='done'?'x':todo.status==='hold'?'>':' '}] [${todo.priority}] ${todo.title}${todo.estimate?` (${todo.estimate})`:''}${todo.due?` [due:${todo.due}]`:''}`;}
function syncFileContent(file){const lines=(file.content||'').split(/\r?\n/);file.todos.forEach(todo=>{if(Number.isInteger(todo.lineIndex))lines[todo.lineIndex]=markdownLine(todo);});file.content=lines.join('\n');}
function markChangedTodoStatuses(file){const lines=(file.content||'').split(/\r?\n/);(file.todos||[]).forEach(todo=>{if(!Number.isInteger(todo.lineIndex))return;const marker=lines[todo.lineIndex]?.match(/^\s*[-*+]\s+\[([ xX>])\]/)?.[1];if(!marker)return;const previousStatus=marker.toLowerCase()==='x'?'done':marker==='>'?'hold':'todo';if(previousStatus!==todo.status)todo.statusChangedAt=new Date().toISOString();});}
async function persistFile(file){const p=project();markChangedTodoStatuses(file);if(!p.folderPath||!file.fileName||!window.electronAPI)return true;syncFileContent(file);const result=await window.electronAPI.writeMarkdown({folderPath:p.folderPath,fileName:file.fileName,content:file.content});if(!result.ok){toast(`파일 저장 실패: ${result.error}`);return false;}file.modifiedAt=new Date().toISOString();return true;}
async function loadGitFileMeta(p){if(!window.electronAPI?.getGitFileMeta||!p?.folderPath)return;await Promise.all((p.files||[]).map(async file=>{const result=await window.electronAPI.getGitFileMeta({folderPath:p.folderPath,fileName:file.fileName});if(result.ok){file.gitModifiedAt=result.lastModified;file.latestCommit=result.latestCommit;file.lineCommits=result.lineCommits;}}));}
function formatModifiedDate(value){return value?String(value).replace('T',' ').slice(0,16):'수정일 없음';}
async function refreshFolder(p,notify=true){if(!p.folderPath||!window.electronAPI)return;const result=await window.electronAPI.readMarkdownFolder(p.folderPath);if(!result.ok){toast(`TODO 폴더를 읽을 수 없습니다: ${result.error}`);return;}const previousFiles=p.files||[];p.files=result.files.map(raw=>{const previous=previousFiles.find(file=>file.fileName===raw.fileName),todos=parseMarkdown(raw.content);todos.forEach(todo=>{const old=previous?.todos?.find(item=>item.lineIndex===todo.lineIndex&&item.title===todo.title);if(old){todo.id=old.id;todo.statusChangedAt=old.status===todo.status?old.statusChangedAt:new Date().toISOString();}});return {id:previous?.id||uid(),name:raw.name,fileName:raw.fileName,isMain:raw.isMain,content:raw.content,modifiedAt:raw.modifiedAt,todos};});await loadGitFileMeta(p);p.folderLoaded=true;p.folderLoadedAt=new Date().toISOString();activeFileId=p.files[0]?.id||null;save();render();if(notify)toast(`${p.files.length}개의 Markdown 파일을 읽었습니다.`);}
function render(){if(syncLinkedDashboardItems())localStorage.setItem(STORAGE_KEY,JSON.stringify(data));document.querySelector('#project-view').hidden=viewMode==='dashboard';document.querySelector('#dashboard-view').hidden=viewMode!=='dashboard';document.querySelector('#dashboard-nav').classList.toggle('active',viewMode==='dashboard');if(viewMode==='dashboard')renderDashboard();else renderProject();}
function renderProject(){const p=project();if(!p)return;const file=activeFile(p);if(file)activeFileId=file.id;const todos=allTodos(p),progressTodos=todos.filter(t=>t.status!=='hold'),done=progressTodos.filter(t=>t.status==='done').length,doing=todos.filter(t=>t.status==='doing').length,progress=progressTodos.length?Math.round(done/progressTodos.length*100):0;document.querySelector('#breadcrumb-project').textContent=p.name;document.querySelector('#project-title').textContent=p.name;document.querySelector('#project-description').textContent=p.description||'설명이 없습니다.';document.querySelector('#project-path').textContent=p.projectPath?`프로젝트 · ${p.projectPath}`:'프로젝트 경로가 설정되지 않았습니다.';document.querySelector('#project-path').title=p.projectPath||'';document.querySelector('#todo-path').textContent=p.folderPath?`TODO · ${p.folderPath}`:'TODO 경로가 설정되지 않았습니다.';document.querySelector('#todo-path').title=p.folderPath||'';const gitStatus=document.querySelector('#project-git-status');gitStatus.textContent=`● ${p.projectPath?gitStatusLabel(p):'프로젝트 경로 미연결'}`;gitStatus.className=`git-project-status ${p.gitStatus||'unknown'}`;document.querySelector('#open-vscode').disabled=!p.projectPath;renderNav();document.querySelector('#stats-grid').innerHTML=`<div class="stat-card"><div class="stat-label">전체 TODO</div><div class="stat-value">${todos.length}<small>items</small></div></div><div class="stat-card"><div class="stat-label">완료</div><div class="stat-value">${done}<small>/ ${progressTodos.length}</small></div></div><div class="stat-card"><div class="stat-label">진행 중</div><div class="stat-value">${doing}<small>active</small></div></div><div class="stat-card"><div class="stat-label">TODO 파일</div><div class="stat-value">${p.files.length}<small>files</small></div></div>`;renderFocus(todos);renderFiles(p,file);renderTodos(file);renderHealth(todos,progress,p.files);renderNotes(p);}
function todayKey(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;}
function setTodoStatus(todo,status){if(todo.status===status)return;todo.status=status;todo.statusChangedAt=new Date().toISOString();}
function dashboardDate(){return new Intl.DateTimeFormat('ko-KR',{weekday:'long',year:'numeric',month:'long',day:'numeric'}).format(new Date());}
function dashboardTypeLabel(type){return {common:'공통',development:'개발',personal:'개인',meeting:'회의',other:'기타'}[type]||'기타';}
function dashboardStatusLabel(status){return {todo:'예정',doing:'진행 중',hold:'보류',done:'완료'}[status]||'예정';}
function renderDashboard(){const items=data.dashboardItems||[],today=todayKey(),todayItems=items.filter(item=>item.date===today).sort((a,b)=>({doing:0,todo:1,hold:2,done:3}[a.status]??1)-({doing:0,todo:1,hold:2,done:3}[b.status]??1));const done=todayItems.filter(item=>item.status==='done').length;document.querySelector('#breadcrumb-project').textContent='오늘 대시보드';document.querySelector('#dashboard-date').textContent=dashboardDate();document.querySelector('#dashboard-stats').innerHTML=`<div class="stat-card"><div class="stat-label">오늘 전체</div><div class="stat-value">${todayItems.length}<small>items</small></div></div><div class="stat-card"><div class="stat-label">완료</div><div class="stat-value">${done}<small>/ ${todayItems.length}</small></div></div><div class="stat-card"><div class="stat-label">진행 중</div><div class="stat-value">${todayItems.filter(item=>item.status==='doing').length}<small>active</small></div></div><div class="stat-card"><div class="stat-label">보류</div><div class="stat-value">${todayItems.filter(item=>item.status==='hold').length}<small>held</small></div></div>`;document.querySelector('#dashboard-today-count').textContent=`${done}/${todayItems.length} 완료`;document.querySelector('#dashboard-items').innerHTML=todayItems.length?todayItems.map(item=>{const projectName=data.projects.find(p=>p.id===item.projectId)?.name;return `<div class="dashboard-item ${item.status==='done'?'completed':''} ${item.status==='hold'?'on-hold':''}"><button class="dashboard-check ${item.status==='done'?'done':''}" data-dashboard-toggle="${item.id}">${item.status==='done'?'✓':''}</button><div class="dashboard-item-main"><div class="dashboard-item-title">${escapeHtml(item.title)}</div><div class="todo-meta"><span class="dashboard-type ${item.type}">${dashboardTypeLabel(item.type)}</span>${projectName?`<span>·</span><span>${escapeHtml(projectName)}</span>`:''}${item.memo?`<span>·</span><span>${escapeHtml(item.memo)}</span>`:''}</div></div><span class="dashboard-status ${item.status}">${dashboardStatusLabel(item.status)}</span><button class="row-action" data-dashboard-edit="${item.id}">편집</button><button class="row-action" data-dashboard-delete="${item.id}">삭제</button></div>`;}).join(''):'<div class="empty">오늘 등록된 작업이 없습니다. 오늘 할 일을 추가해보세요.</div>';document.querySelector('#dashboard-projects').innerHTML=data.projects.map(p=>{const todos=allTodos(p),progressTodos=todos.filter(t=>t.status!=='hold'),done=progressTodos.filter(t=>t.status==='done').length,percent=progressTodos.length?Math.round(done/progressTodos.length*100):0;return `<button class="dashboard-project" data-dashboard-project="${p.id}"><span><i class="project-dot" style="background:${p.color||'var(--accent-2)'}"></i>${escapeHtml(p.name)}</span><span>${percent}% <small>${done}/${progressTodos.length}</small></span></button>`;}).join('')||'<div class="empty">프로젝트가 없습니다.</div>';document.querySelectorAll('[data-dashboard-toggle]').forEach(b=>b.onclick=()=>toggleDashboardItem(b.dataset.dashboardToggle));document.querySelectorAll('[data-dashboard-edit]').forEach(b=>b.onclick=()=>openDashboardModal(b.dataset.dashboardEdit));document.querySelectorAll('[data-dashboard-delete]').forEach(b=>b.onclick=()=>deleteDashboardItem(b.dataset.dashboardDelete));document.querySelectorAll('[data-dashboard-project]').forEach(b=>b.onclick=()=>{data.selectedProjectId=b.dataset.dashboardProject;viewMode='project';activeFileId=null;save();render();});}
function gitStatusLabel(p){return p.gitStatus==='connected'?'Git 연결됨':p.gitStatus==='disconnected'?'Git 미연결':'확인 중';}
async function checkGitStatus(p){if(!p?.projectPath||!window.electronAPI?.getGitStatus)return;if(p.gitStatusCheckedPath===p.projectPath)return;p.gitStatusCheckedPath=p.projectPath;const result=await window.electronAPI.getGitStatus(p.projectPath);p.gitStatus=result.connected?'connected':'disconnected';save();render();}
function renderNav(){document.querySelector('#project-nav').innerHTML=data.projects.map(p=>`<button class="project-item ${viewMode==='project'&&p.id===data.selectedProjectId?'active':''}" data-project="${p.id}"><i class="project-dot" style="background:${p.color||'var(--accent-2)'}"></i><span class="project-name">${escapeHtml(p.name)}</span><span class="git-badge ${p.gitStatus||'unknown'}">${gitStatusLabel(p)}</span><span class="project-count">${allTodos(p).filter(t=>t.status!=='done').length}</span></button>`).join('');data.projects.forEach(checkGitStatus);document.querySelectorAll('[data-project]').forEach(b=>b.onclick=async()=>{data.selectedProjectId=b.dataset.project;viewMode='project';activeFileId=null;const p=project();if(p.folderPath&&!p.folderLoaded)await refreshFolder(p,false);await checkGitStatus(p);save();render();});}
function renderFocus(todos){const next=todos.find(t=>t.status==='doing')||todos.find(t=>t.status==='todo');document.querySelector('#next-todo-card').innerHTML=next?`<div class="focus-content"><div class="focus-icon">→</div><div><p class="eyebrow">NEXT UP · ${next.priority.toUpperCase()} PRIORITY</p><h3>${escapeHtml(next.title)}</h3><p>이 항목을 완료하면 다음 작업으로 넘어갈 수 있습니다. 예상 ${escapeHtml(next.estimate||'미정')}</p></div><span class="focus-tag">${next.status==='doing'?'진행 중':'다음 작업'}</span></div>`:`<div class="focus-content"><div class="focus-icon">✓</div><div><p class="eyebrow">ALL CLEAR</p><h3>현재 프로젝트의 TODO를 모두 완료했습니다.</h3><p>새로운 TODO를 추가하거나 다음 프로젝트로 이동해보세요.</p></div></div>`;}
function fileProgress(file){const eligible=file?.todos.filter(t=>t.status!=='hold')||[],total=eligible.length,done=eligible.filter(t=>t.status==='done').length;return {total,done,percent:total?Math.round(done/total*100):0};}
function renderFiles(p,file){document.querySelector('#file-tabs').innerHTML=p.files.length?p.files.map(f=>`<button class="file-tab ${f.id===file?.id?'active':''}" data-file="${f.id}">${f.isMain?'★ ':''}${escapeHtml(f.name)}<span>${f.todos.length} · ${formatModifiedDate(f.gitModifiedAt||f.modifiedAt)}</span></button>`).join(''):'<div class="empty">연결된 폴더에 Markdown 파일이 없습니다.</div>';document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{activeFileId=b.dataset.file;render();});const stats=fileProgress(file),commit=file?.latestCommit;document.querySelector('#file-meta').innerHTML=`${file?.isMain?'메인 TODO · ':''}${file?.name||'TODO 파일'} · ${stats.done}/${stats.total}개 완료 · ${stats.percent}%${commit?` · 마지막 커밋 <span class="commit-info" title="${escapeHtml(`${commit.author} · ${commit.message}`)}">${escapeHtml(commit.hash)} · ${escapeHtml(commit.message)}</span>`:file?` · 파일 수정 ${formatModifiedDate(file.modifiedAt)}`:''}`;}
function renderTodos(file){const list=(file?.todos||[]).filter(t=>filter==='all'||t.status===filter);document.querySelector('#todo-list').innerHTML=list.length?list.map(t=>{const commit=file?.lineCommits?.[t.lineIndex];const changeInfo=commit?`변경 ${formatModifiedDate(commit.date)} · ${commit.hash}`:`파일 변경 ${formatModifiedDate(file?.gitModifiedAt||file?.modifiedAt)}`;return `<div class="todo-row ${t.status==='done'?'completed':''} ${t.status==='hold'?'on-hold':''}"><button class="check ${t.status==='done'?'done':''} ${t.status==='hold'?'hold':''}" data-toggle="${t.id}">${t.status==='done'?'✓':t.status==='hold'?'›':''}</button><div><div class="todo-title">${escapeHtml(t.title)}</div><div class="todo-meta"><span class="priority ${t.priority}">${t.priority==='high'?'높음':t.priority==='medium'?'보통':'낮음'}</span><span>·</span><span>${escapeHtml(t.estimate||'예상 시간 미정')}</span>${t.due?`<span>·</span><span class="todo-due">${escapeHtml(t.due.replace('T',' '))}</span>`:''}<span>·</span><span>${t.status==='doing'?'진행 중':t.status==='hold'?'보류':t.status==='done'?'완료':'예정'}</span><span>·</span><span class="todo-modified" title="${escapeHtml(commit?`${commit.author} · ${commit.message}`:'파일 수정일 기준')}">${escapeHtml(changeInfo)}</span></div></div><div class="todo-actions"><button class="row-action" data-edit="${t.id}">편집</button><button class="row-action" data-delete="${t.id}">삭제</button></div></div>`;}).join(''):'<div class="empty">이 필터에 해당하는 TODO가 없습니다.</div>';document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggleTodo(b.dataset.toggle));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openTodoModal(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteTodo(b.dataset.delete));}
function renderHealth(todos,progress,files=[]){const fileRows=files.length?files.map(file=>{const stats=fileProgress(file);return `<button class="file-progress-row" data-file="${file.id}"><span class="file-progress-name">${file.isMain?'★ ':''}${escapeHtml(file.name)}</span><span class="file-progress-track"><i style="width:${stats.percent}%"></i></span><span class="file-progress-value">${stats.percent}% <small>${stats.done}/${stats.total}</small></span></button>`;}).join(''):'<div class="empty">연결된 TODO 파일이 없습니다.</div>';document.querySelector('#health-content').innerHTML=`<div class="health-ring" style="--progress:${progress}%"><div><strong>${progress}%</strong><span>전체 완료율</span></div></div><div class="health-lines"><div class="health-line"><span>완료</span><b>${todos.filter(t=>t.status==='done').length}</b></div><div class="health-line"><span>진행 중</span><b>${todos.filter(t=>t.status==='doing').length}</b></div><div class="health-line"><span>남은 항목</span><b>${todos.filter(t=>t.status!=='done'&&t.status!=='hold').length}</b></div></div><div class="file-progress-list"><div class="file-progress-heading">파일별 진행률</div>${fileRows}</div>`;document.querySelectorAll('.file-progress-row').forEach(b=>b.onclick=()=>{activeFileId=b.dataset.file;render();});}
function renderNotes(p){document.querySelector('#notes-list').innerHTML=p.notes?.length?p.notes.map((n,i)=>`<div class="note">${escapeHtml(n)}<button data-note="${i}">×</button></div>`).join(''):'<div class="empty">아직 메모가 없습니다.</div>';document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{p.notes.splice(+b.dataset.note,1);save();render();});}
async function toggleTodo(id){const p=project(),f=p.files.find(file=>file.todos.some(t=>t.id===id)),t=f?.todos.find(item=>item.id===id);if(!t)return;setTodoStatus(t,t.status==='done'?'todo':'done');if(await persistFile(f)){save();render();toast(t.status==='done'?'TODO 완료 및 파일 저장':'TODO를 예정으로 변경');}}
async function deleteTodo(id){const p=project(),f=p.files.find(file=>file.todos.some(t=>t.id===id));if(!f)return;const index=f.todos.findIndex(t=>t.id===id),removed=f.todos[index];f.todos.splice(index,1);if(Number.isInteger(removed?.lineIndex))f.todos.slice(index).forEach(t=>{if(t.lineIndex>removed.lineIndex)t.lineIndex--;});if(p.folderPath&&f.fileName&&Number.isInteger(removed?.lineIndex)){const lines=(f.content||'').split(/\r?\n/);lines.splice(removed.lineIndex,1);f.content=lines.join('\n');const result=await window.electronAPI.writeMarkdown({folderPath:p.folderPath,fileName:f.fileName,content:f.content});if(!result.ok){toast(`파일 저장 실패: ${result.error}`);return;}}save();render();toast('TODO를 삭제했습니다.');}
function modal(title,body,submit){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2>${body}<div class="modal-actions"><button class="cancel" id="modal-cancel">취소</button><button class="confirm" id="modal-submit">저장</button></div></div></div>`;document.querySelector('#modal-cancel').onclick=closeModal;document.querySelector('#modal-submit').onclick=submit;document.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();};}
function closeModal(){document.querySelector('#modal-root').innerHTML='';}
function pathField(kind,label,value='',placeholder=''){return `<div class="form-field"><label>${label}</label><div class="path-input-row"><input id="m-${kind}-path" value="${escapeHtml(value)}" placeholder="${escapeHtml(placeholder)}" /><button id="m-browse-${kind}" type="button">폴더 선택</button></div></div>`;}
function bindPathPicker(kind){const button=document.querySelector(`#m-browse-${kind}`);if(!button)return;button.onclick=async()=>{if(!window.electronAPI?.chooseFolder)return toast('폴더 선택은 Electron 앱에서 사용할 수 있습니다.');const input=document.querySelector(`#m-${kind}-path`),folder=await window.electronAPI.chooseFolder({defaultPath:input.value.trim()||undefined});if(folder)input.value=folder;};}
function bindPathPickers(){bindPathPicker('project');bindPathPicker('todo');}
async function validatedFolderPath(value){const folderPath=value.trim();if(!folderPath)return {ok:true,path:''};if(!window.electronAPI?.validateFolder)return {ok:true,path:folderPath};return window.electronAPI.validateFolder(folderPath);}
