function openFileModal(){const p=project();if(!p.folderPath)return toast('먼저 TODO 폴더를 연결해주세요.');modal('새 TODO 파일',`<div class="form-field"><label>파일 이름</label><input id="m-name" placeholder="예: 2차 개선, 버그 수정" autofocus /></div>`,async()=>{let name=document.querySelector('#m-name').value.trim();if(!name)return toast('파일 이름을 입력해주세요.');if(!name.toLowerCase().endsWith('.md'))name+='.md';const result=await window.electronAPI.createMarkdown({folderPath:p.folderPath,fileName:name,content:'# TODO\n\n'});if(!result.ok)return toast(`파일 생성 실패: ${result.error}`);closeModal();await refreshFolder(p);toast('Markdown TODO 파일을 만들었습니다.');});}
function openProjectModal(){const p=project();modal('프로젝트 편집',`<div class="form-field"><label>프로젝트 이름</label><input id="m-name" value="${escapeHtml(p.name)}" autofocus /></div><div class="form-field"><label>설명</label><textarea id="m-description">${escapeHtml(p.description||'')}</textarea></div>${pathField('project','프로젝트 경로',p.projectPath,'예: D:\\project\\my-app')}${pathField('todo','TODO 경로',p.folderPath,'예: D:\\project\\my-app\\todo')}`,async()=>{const name=document.querySelector('#m-name').value.trim();if(!name)return toast('프로젝트 이름을 입력해주세요.');const [projectValidation,todoValidation]=await Promise.all([validatedFolderPath(document.querySelector('#m-project-path').value),validatedFolderPath(document.querySelector('#m-todo-path').value)]);if(!projectValidation.ok)return toast(`프로젝트 경로: ${projectValidation.error}`);if(!todoValidation.ok)return toast(`TODO 경로: ${todoValidation.error}`);const todoPathChanged=p.folderPath!==todoValidation.path;p.name=name;p.description=document.querySelector('#m-description').value.trim();p.projectPath=projectValidation.path;p.folderPath=todoValidation.path;p.gitStatus=null;p.gitStatusCheckedPath=null;if(todoPathChanged)p.folderLoaded=false;closeModal();if(todoPathChanged&&p.folderPath){await refreshFolder(p);toast('프로젝트 정보와 TODO 경로를 저장했습니다.');}else{if(todoPathChanged){p.files=[];activeFileId=null;}save();render();toast('프로젝트 정보를 저장했습니다.');}});bindPathPickers();}
function mainTodoRows(){return data.projects.flatMap(p=>{const file=p.files.find(entry=>entry.isMain);return file?(file.todos||[]).map(todo=>({project:p,file,todo})):[];});}
function linkedMainTodo(item){if(!item?.mainTodoId||!item.projectId)return null;const p=data.projects.find(entry=>entry.id===item.projectId),file=p?.files.find(entry=>entry.isMain),todo=file?.todos.find(entry=>entry.id===item.mainTodoId);return p&&file&&todo?{project:p,file,todo}:null;}
function todoDueDate(todo){return todo?.due?.match(/^\d{4}-\d{2}-\d{2}/)?.[0]||'';}
function setTodoDueDate(todo,date){if(!date){todo.due='';return;}const time=todo?.due?.match(/T(\d{2}:\d{2})/)?.[1]||'09:00';todo.due=`${date}T${time}`;}
function syncLinkedDashboardItems(){
  let changed=false;
  if(!Array.isArray(data.dashboardItems))data.dashboardItems=[];
  const rows=mainTodoRows();
  rows.forEach(({project:p,todo})=>{
    const date=todoDueDate(todo);
    if(!date)return;
    let item=data.dashboardItems.find(entry=>entry.projectId===p.id&&entry.mainTodoId===todo.id);
    if(!item){item={id:uid(),projectId:p.id,mainTodoId:todo.id,date,type:'development',memo:'',status:todo.status,title:todo.title,mainTodoAuto:true,mainTodoDateLinked:true};data.dashboardItems.push(item);changed=true;}
    else if(!item.mainTodoDateLinked){item.mainTodoDateLinked=true;changed=true;}
  });
  data.dashboardItems=[...data.dashboardItems].filter(item=>{
    const linked=linkedMainTodo(item);
    if(item.mainTodoId&&!linked){delete item.mainTodoId;delete item.mainTodoAuto;changed=true;return true;}
    if(!linked)return true;
    const dueDate=todoDueDate(linked.todo);
    if((item.mainTodoAuto||item.mainTodoDateLinked)&&!dueDate){changed=true;return false;}
    const values={title:linked.todo.title,status:linked.todo.status,type:'development',projectId:linked.project.id,...(dueDate?{date:dueDate}:{})};
    Object.entries(values).forEach(([key,value])=>{if(item[key]!==value){item[key]=value;changed=true;}});
    return true;
  });
  return changed;
}
