async function toggleDashboardItem(id){const item=data.dashboardItems.find(entry=>entry.id===id);if(!item)return;const oldStatus=item.status,nextStatus=oldStatus==='done'?'todo':'done',linked=linkedMainTodo(item);item.status=nextStatus;if(linked){linked.todo.status=nextStatus;if(!(await persistMainTodo(linked.project,linked.file))){item.status=oldStatus;linked.todo.status=oldStatus;syncFileContent(linked.file);return;}}save();render();}
async function deleteDashboardItem(id){const index=data.dashboardItems.findIndex(item=>item.id===id);if(index<0)return;const item=data.dashboardItems[index],linked=linkedMainTodo(item);if(!confirm(linked?'요일별 작업에서 제거하고 메인 TODO의 일시도 비울까요?':'이 일정·작업을 삭제할까요?'))return;if(linked){const oldDue=linked.todo.due;linked.todo.due='';if(!(await persistMainTodo(linked.project,linked.file))){linked.todo.due=oldDue;syncFileContent(linked.file);return;}}data.dashboardItems.splice(index,1);save();render();toast(linked?'요일별 작업과 메인 TODO 일시를 해제했습니다.':'일정·작업을 삭제했습니다.');}
