function weekDays(){const now=new Date(),day=now.getDay(),daysSinceMonday=(day+6)%7,monday=new Date(now);monday.setDate(now.getDate()-daysSinceMonday);const friday=new Date(monday);friday.setDate(monday.getDate()-3);return [{offset:0,label:'금요일'},{offset:3,label:'월요일'},{offset:4,label:'화요일'},{offset:5,label:'수요일'},{offset:6,label:'목요일'}].map(({offset,label})=>{const date=new Date(friday);date.setDate(friday.getDate()+offset);return {key:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,label,date};});}
function weeklyDashboard(){const days=weekDays(),keys=new Set(days.map(day=>day.key)),items=(data.dashboardItems||[]).filter(item=>keys.has(item.date)),done=items.filter(item=>item.status==='done').length;document.querySelector('#breadcrumb-project').textContent='이번 주 대시보드';document.querySelector('#dashboard-date').textContent=`${days[0].key.replaceAll('-','.')} — ${days[days.length-1].key.replaceAll('-','.')} · 전주 금요일부터 이번 주 목요일까지`;document.querySelector('#dashboard-stats').innerHTML=`<div class="stat-card"><div class="stat-label">이번 주 전체</div><div class="stat-value">${items.length}<small>items</small></div></div><div class="stat-card"><div class="stat-label">완료</div><div class="stat-value">${done}<small>/ ${items.length}</small></div></div><div class="stat-card"><div class="stat-label">진행 중</div><div class="stat-value">${items.filter(item=>item.status==='doing').length}<small>active</small></div></div><div class="stat-card"><div class="stat-label">보류</div><div class="stat-value">${items.filter(item=>item.status==='hold').length}<small>held</small></div></div>`;document.querySelector('#dashboard-today-count').textContent=`${done}/${items.length} 완료`;document.querySelector('#dashboard-items').innerHTML=days.map(day=>{const dayItems=items.filter(item=>item.date===day.key).sort((a,b)=>({doing:0,todo:1,hold:2,done:3}[a.status]??1)-({doing:0,todo:1,hold:2,done:3}[b.status]??1));return `<section class="weekday-group"><div class="weekday-heading"><strong>${day.label}</strong><span>${day.key.replaceAll('-','.')}</span><em>${dayItems.length}개</em></div>${dayItems.length?dayItems.map(item=>{const projectName=data.projects.find(p=>p.id===item.projectId)?.name;return `<div class="dashboard-item ${item.status==='done'?'completed':''} ${item.status==='hold'?'on-hold':''}"><button class="dashboard-check ${item.status==='done'?'done':''}" data-dashboard-toggle="${item.id}">${item.status==='done'?'✓':''}</button><div class="dashboard-item-main"><div class="dashboard-item-title">${escapeHtml(item.title)}</div><div class="todo-meta"><span class="dashboard-type ${item.type}">${dashboardTypeLabel(item.type)}</span>${projectName?`<span>·</span><span>${escapeHtml(projectName)}</span>`:''}${item.memo?`<span>·</span><span>${escapeHtml(item.memo)}</span>`:''}</div></div><span class="dashboard-status ${item.status}">${dashboardStatusLabel(item.status)}</span><button class="row-action" data-dashboard-edit="${item.id}">편집</button><button class="row-action" data-dashboard-delete="${item.id}">삭제</button></div>`;}).join(''):'<div class="weekday-empty">등록된 작업 없음</div>'}</section>`;}).join('');document.querySelectorAll('[data-dashboard-toggle]').forEach(b=>b.onclick=()=>toggleDashboardItem(b.dataset.dashboardToggle));document.querySelectorAll('[data-dashboard-edit]').forEach(b=>b.onclick=()=>openDashboardModal(b.dataset.dashboardEdit));document.querySelectorAll('[data-dashboard-delete]').forEach(b=>b.onclick=()=>deleteDashboardItem(b.dataset.dashboardDelete));}
function generateWeeklyReport(){const days=weekDays(),keys=new Set(days.map(day=>day.key)),items=(data.dashboardItems||[]).filter(item=>keys.has(item.date)),lines=[`# VibeTodo 주간 진행 보고서`,'',`- 기간: ${days[0].key} ~ ${days[days.length-1].key}`,`- 생성일: ${todayKey()}`,'',`## 요약`,'',`- 전체 작업: ${items.length}개`,`- 완료: ${items.filter(item=>item.status==='done').length}개`,`- 진행 중: ${items.filter(item=>item.status==='doing').length}개`,`- 보류: ${items.filter(item=>item.status==='hold').length}개`,'','## 요일별 진행 내용',''];days.forEach(day=>{lines.push(`### ${day.label} (${day.key})`,'');const dayItems=items.filter(item=>item.date===day.key);if(!dayItems.length){lines.push('- 등록된 작업 없음','');return;}dayItems.forEach(item=>lines.push(`- [${item.status==='done'?'x':' '}] [${dashboardTypeLabel(item.type)}] ${item.title}${item.memo?` — ${item.memo}`:''}`));lines.push('');});const blob=new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`vibetodo-weekly-report-${days[0].key}.md`;a.click();URL.revokeObjectURL(a.href);toast('주간 진행 보고서를 만들었습니다.');}
document.querySelector('#dashboard-nav').onclick=()=>{viewMode='dashboard';render();};document.querySelector('#weekly-report').onclick=generateWeeklyReport;document.querySelector('#new-dashboard-item').onclick=()=>openDashboardModal();document.querySelector('#new-project').onclick=newProject;document.querySelector('#new-file').onclick=openFileModal;document.querySelector('#edit-project').onclick=openProjectModal;document.querySelector('#open-vscode').onclick=openProjectInVSCode;document.querySelector('#status-filter').onchange=e=>{filter=e.target.value;render();};document.querySelector('#add-note').onclick=()=>{modal('새 메모',`<div class="form-field"><label>메모</label><textarea id="m-note" placeholder="기억해둘 내용이나 다음에 확인할 점"></textarea></div>`,()=>{const note=document.querySelector('#m-note').value.trim();if(!note)return toast('메모 내용을 입력해주세요.');project().notes.push(note);save();closeModal();render();});};document.querySelector('#export-data').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`vibetodo-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('백업 파일을 내보냈습니다.');};document.querySelector('#import-data').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{data=JSON.parse(reader.result);if(!Array.isArray(data.dashboardItems))data.dashboardItems=[];data=separateProjectPaths(data);activeFileId=null;save();render();toast('백업을 복원했습니다.');}catch{toast('올바른 JSON 백업 파일이 아닙니다.');}};reader.readAsText(file);}
document.querySelector('#sync-files').onclick=syncFiles;document.querySelector('#new-todo').onclick=()=>{if(!activeFile(project()))return toast('먼저 TODO 파일을 선택해주세요.');openTodoModal();};
function reportPeriod(offset=0){const now=new Date(),day=now.getDay(),end=new Date(now);let daysBack=day===4?0:(day+7-4)%7||7;end.setDate(now.getDate()-daysBack-(offset*7));end.setHours(0,0,0,0);const start=new Date(end);start.setDate(end.getDate()-6);return {start:dateKey(start),end:dateKey(end)};}
function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function reportDraft(period){const items=(data.dashboardItems||[]).filter(item=>item.date>=period.start&&item.date<=period.end),lines=[`# VibeTodo 주간 진행 보고서`,'',`- 보고 기간: ${period.start} ~ ${period.end}`,`- 작성일: ${todayKey()}`,'','## 요약','',`- 전체 작업: ${items.length}개`,`- 완료: ${items.filter(item=>item.status==='done').length}개`,`- 진행 중: ${items.filter(item=>item.status==='doing').length}개`,`- 보류: ${items.filter(item=>item.status==='hold').length}개`,'','## 업무 진행 내용',''];items.forEach(item=>lines.push(`- [${item.status==='done'?'x':' '}] [${dashboardTypeLabel(item.type)}] ${item.title}${item.memo?` — ${item.memo}`:''}`));lines.push('','## 다음 주 계획','','- ','','## 이슈 및 지원 요청','','- ');return lines.join('\n');}
function openWeeklyReportModal(report=null){const period=report?{start:report.startDate,end:report.endDate}:reportPeriod(),old=report||data.weeklyReports.find(item=>item.startDate===period.start&&item.endDate===period.end),content=old?.content||reportDraft(period);modal(old?'주간 보고서 확인':'주간 보고서 작성',`<p class="report-period">보고 기간: ${period.start} ~ ${period.end}<br>목요일 오후 또는 금요일 오전에 작성할 수 있습니다.</p><div class="form-field"><label>진행 보고서</label><textarea id="m-weekly-report" class="report-editor">${escapeHtml(content)}</textarea></div><button id="m-report-download" class="text-button report-download" type="button">↗ Markdown으로 다운로드</button>`,()=>{const next={id:old?.id||uid(),startDate:period.start,endDate:period.end,content:document.querySelector('#m-weekly-report').value,updatedAt:new Date().toISOString()};if(old){const index=data.weeklyReports.findIndex(item=>item.id===old.id);data.weeklyReports[index]=next;}else data.weeklyReports.push(next);save();closeModal();render();toast('주간 보고서를 저장했습니다.');});document.querySelector('#m-report-download').onclick=()=>{const blob=new Blob([document.querySelector('#m-weekly-report').value],{type:'text/markdown;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`vibetodo-report-${period.start}.md`;a.click();URL.revokeObjectURL(a.href);};}
function renderWeeklyReportHistory(){const reports=[...(data.weeklyReports||[])].sort((a,b)=>b.endDate.localeCompare(a.endDate)).slice(0,3);document.querySelector('#weekly-report-history').innerHTML=reports.length?reports.map(report=>`<button class="weekly-report-entry" data-report-id="${report.id}"><span>${report.startDate} ~ ${report.endDate}</span><small>${report.updatedAt?.slice(0,10)||'저장됨'}</small></button>`).join(''):'<div class="empty">작성한 보고서가 없습니다.</div>';document.querySelectorAll('[data-report-id]').forEach(button=>button.onclick=()=>openWeeklyReportModal(data.weeklyReports.find(report=>report.id===button.dataset.reportId)));}
if(window.electronAPI)window.electronAPI.getAppInfo().then(info=>{const badge=document.querySelector('#runtime-badge');if(badge)badge.textContent=`ELECTRON ${info.version}`;});
const renderDashboardContent=renderDashboard;renderDashboard=()=>{renderNav();weeklyDashboard();renderDashboardMainTodos();renderWeeklyReportHistory();document.querySelector('#weekly-report').textContent='▤ 주간 Git 활동 확인';};
document.querySelector('#weekly-report').onclick=openWeeklyReportModal;
async function loadReportActivity(period){const target=document.querySelector('#report-activity');if(!target)return;const changedFiles=data.projects.flatMap(p=>(p.files||[]).filter(file=>file.modifiedAt&&file.modifiedAt.slice(0,10)>=period.start&&file.modifiedAt.slice(0,10)<=period.end).map(file=>`${p.name}/${file.name}`));if(!window.electronAPI||!project()?.projectPath){target.innerHTML=changedFiles.length?`<div class="report-activity-title">앱이 마지막으로 읽은 파일 수정 시각 기준 · ${changedFiles.length}개 파일</div>${changedFiles.map(file=>`<div class="report-commit"><b>${escapeHtml(file)}</b></div>`).join('')}`:'<div class="activity-muted">프로젝트 경로가 없어 Git 활동을 확인할 수 없습니다.</div>';return;}target.innerHTML='<div class="activity-muted">Git 수정 내역을 확인하는 중…</div>';const result=await window.electronAPI.getGitPeriodLog({folderPath:project().projectPath,since:period.start,until:period.end});if(!result.ok){target.innerHTML=changedFiles.length?`<div class="report-activity-title">Git 기록 없음 · 파일 수정 시각 기준 · ${changedFiles.length}개 파일</div>${changedFiles.map(file=>`<div class="report-commit"><b>${escapeHtml(file)}</b></div>`).join('')}`:`<div class="activity-muted">${escapeHtml(result.error)}</div>`;return;}target.innerHTML=result.commits.length?`<div class="report-activity-title">해당 기간 Git 활동 · ${result.commits.length}개 커밋 · ${result.files.length}개 파일</div>${result.commits.slice(0,8).map(commit=>`<div class="report-commit"><span>${escapeHtml(commit.date)}</span><b>${escapeHtml(commit.message)}</b><small>${escapeHtml(commit.hash)} · ${commit.files.length}개 파일</small></div>`).join('')}`:changedFiles.length?`<div class="report-activity-title">Git 커밋 없음 · 파일 수정 시각 기준 · ${changedFiles.length}개 파일</div>${changedFiles.map(file=>`<div class="report-commit"><b>${escapeHtml(file)}</b></div>`).join('')}`:'<div class="activity-muted">해당 기간에 Git 커밋과 파일 수정 내역이 없습니다.</div>';}
async function loadAllProjectActivity(period){const target=document.querySelector('#report-activity');if(!target)return;target.innerHTML='<div class="activity-muted">프로젝트별 Git 활동을 확인하는 중…</div>';const rows=await Promise.all(data.projects.map(async p=>{if(!p.projectPath||!window.electronAPI?.getGitPeriodLog)return {project:p,skip:true};const result=await window.electronAPI.getGitPeriodLog({folderPath:p.projectPath,since:period.start,until:period.end});return {project:p,result};}));const visible=rows.filter(row=>!row.skip);if(!visible.length){target.innerHTML='<div class="activity-muted">프로젝트 경로가 연결된 항목이 없습니다.</div>';return;}target.innerHTML=visible.map(({project:p,result})=>{if(!result.ok)return `<section class="report-project-activity"><h3>${escapeHtml(p.name)} <small>Git 미연결</small></h3><div class="activity-muted">${escapeHtml(result.error)}</div></section>`;if(!result.commits.length)return `<section class="report-project-activity"><h3>${escapeHtml(p.name)} <small>변경 없음</small></h3><div class="activity-muted">해당 기간 Git 커밋이 없습니다.</div></section>`;return `<section class="report-project-activity"><h3>${escapeHtml(p.name)} <small>${result.commits.length}개 커밋 · ${result.files.length}개 파일</small></h3>${result.commits.map(commit=>`<div class="report-commit"><span>${escapeHtml(commit.date)}</span><b>${escapeHtml(commit.message)}</b><small>${escapeHtml(commit.hash)} · ${commit.files.map(escapeHtml).join(', ')}</small></div>`).join('')}</section>`;}).join('');}
function openReportComposer(offset=0){const period=reportPeriod(offset);modal('주간 Git 활동 확인',`<p class="report-period">확인 기간: ${period.start} ~ ${period.end}<br>작성·저장 없이 프로젝트별 Git 커밋과 변경된 TODO 파일을 확인합니다.</p><div id="report-activity" class="report-activity"><div class="activity-muted">Git 수정 내역을 확인하는 중…</div></div>`,()=>closeModal());document.querySelector('#modal-submit').style.display='none';document.querySelector('#modal-cancel').textContent='닫기';loadAllProjectActivity(period);}
function renderPeriodHistory(){const current=reportPeriod(0),previous=reportPeriod(1);document.querySelector('#weekly-report-history').innerHTML=`<button class="weekly-report-entry" data-report-period="0"><span>현재 보고 기간<br><small>${current.start} ~ ${current.end}</small></span><small>활동 확인</small></button><button class="weekly-report-entry" data-report-period="1"><span>직전 보고 기간<br><small>${previous.start} ~ ${previous.end}</small></span><small>활동 확인</small></button>`;document.querySelectorAll('[data-report-period]').forEach(button=>button.onclick=()=>openReportComposer(Number(button.dataset.reportPeriod)));}
renderWeeklyReportHistory=renderPeriodHistory;
document.querySelector('#weekly-report').onclick=openReportComposer;
render();
